:root {
  --ink: #142019;
  --cream: #f4e9c9;
  --cream-dim: #cdbf9b;
  --gold: #e9c66b;
  --gold-bright: #ffe49a;
  --gold-deep: #a97a32;
  --moss: #6f9a5c;
  --moss-deep: #2d4a37;
  --panel: rgba(16, 27, 21, 0.78);
  --panel-edge: rgba(238, 210, 141, 0.28);
  --shadow: 0 18px 60px rgba(4, 10, 7, 0.55);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  font-synthesis: none;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #0b1511;
  color: var(--cream);
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}

body {
  font-family: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, ui-serif, serif;
  touch-action: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% 10%, #314b35 0%, #16261d 50%, #0a120e 100%);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(5, 12, 8, 0.18) 74%, rgba(4, 9, 6, 0.6) 118%),
    linear-gradient(to bottom, rgba(8, 15, 11, 0.26), transparent 16%, transparent 82%, rgba(6, 12, 8, 0.34));
  mix-blend-mode: multiply;
}

.sun-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(70% 60% at 18% 2%, rgba(255, 226, 150, 0.16), transparent 62%),
    linear-gradient(160deg, rgba(255, 218, 130, 0.06), transparent 38%);
  mix-blend-mode: screen;
}

.hud {
  position: absolute;
  z-index: 10;
}

.hud-top {
  top: calc(var(--safe-top) + 14px);
  left: calc(var(--safe-left) + 16px);
  right: calc(var(--safe-right) + 16px);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 13px 8px 10px;
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(20, 32, 24, 0.78), rgba(12, 21, 16, 0.7));
  border: 1px solid var(--panel-edge);
  box-shadow: 0 10px 28px rgba(3, 8, 5, 0.32), inset 0 1px 0 rgba(255, 239, 194, 0.07);
  backdrop-filter: blur(8px);
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  color: var(--gold);
  background: radial-gradient(circle at 35% 25%, rgba(255, 230, 160, 0.2), rgba(21, 37, 27, 0.5));
  border: 1px solid rgba(235, 201, 112, 0.4);
  box-shadow: inset 0 0 12px rgba(239, 202, 104, 0.1);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.05;
}

.brand-text strong {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #f7eccb;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.4);
}

.brand-text small {
  margin-top: 3px;
  font-size: 9px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(220, 204, 162, 0.62);
}

.quest {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 9px 18px 10px;
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(18, 30, 22, 0.76), rgba(11, 19, 14, 0.62));
  border: 1px solid rgba(238, 210, 141, 0.22);
  box-shadow: 0 12px 34px rgba(3, 8, 5, 0.32), inset 0 1px 0 rgba(255, 239, 194, 0.06);
  backdrop-filter: blur(8px);
  transition: transform 0.35s cubic-bezier(.2,.9,.3,1), background 0.5s ease;
}

.quest.complete {
  border-color: rgba(255, 223, 132, 0.6);
  box-shadow: 0 0 32px rgba(244, 201, 91, 0.24), 0 12px 34px rgba(3, 8, 5, 0.32);
}

.quest-label {
  font-size: 9px;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: rgba(233, 215, 171, 0.72);
}

.bloom-track {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bloom {
  position: relative;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  color: rgba(166, 186, 145, 0.28);
  font-size: 15px;
  line-height: 1;
  transition: color 0.4s ease, transform 0.4s cubic-bezier(.2,1.6,.4,1), filter 0.4s ease;
}

.bloom::before {
  content: "✦";
  filter: drop-shadow(0 0 0 transparent);
}

.bloom.filled {
  color: var(--gold-bright);
  transform: scale(1.16);
  filter: drop-shadow(0 0 7px rgba(255, 213, 100, 0.75));
}

.bloom.pop { animation: bloom-pop 0.55s cubic-bezier(.2,1.8,.4,1); }

@keyframes bloom-pop {
  0% { transform: scale(0.5) rotate(-30deg); }
  60% { transform: scale(1.5) rotate(8deg); }
  100% { transform: scale(1.16); }
}

.icon-button {
  pointer-events: auto;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--panel-edge);
  color: rgba(243, 229, 193, 0.8);
  background: linear-gradient(180deg, rgba(22, 35, 26, 0.78), rgba(12, 21, 16, 0.7));
  backdrop-filter: blur(8px);
  cursor: pointer;
  transition: color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}

.icon-button:hover { color: var(--gold-bright); border-color: rgba(238, 210, 141, 0.55); transform: translateY(-1px); }
.icon-button:active { transform: scale(0.94); }
.icon-button .sound-off { display: none; }
.icon-button.muted .sound-on { display: none; }
.icon-button.muted .sound-off { display: block; }

.toast {
  position: absolute;
  z-index: 12;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 136px);
  transform: translate(-50%, 12px);
  max-width: min(84vw, 520px);
  padding: 10px 20px;
  border-radius: 999px;
  text-align: center;
  font-size: 13px;
  letter-spacing: 0.06em;
  color: #f7eccd;
  background: linear-gradient(180deg, rgba(20, 33, 24, 0.88), rgba(11, 20, 15, 0.84));
  border: 1px solid rgba(236, 207, 135, 0.24);
  box-shadow: 0 14px 38px rgba(3, 8, 5, 0.4);
  backdrop-filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.45s ease, transform 0.45s cubic-bezier(.2,.9,.3,1);
}

.toast.visible { opacity: 1; transform: translate(-50%, 0); }
.toast.gold { color: var(--gold-bright); border-color: rgba(255, 220, 128, 0.5); box-shadow: 0 0 28px rgba(240, 197, 86, 0.2), 0 14px 38px rgba(3, 8, 5, 0.4); }

/* Joystick */
.joystick-wrap {
  position: absolute;
  z-index: 9;
  left: calc(var(--safe-left) + clamp(18px, 4.2vw, 46px));
  bottom: calc(var(--safe-bottom) + clamp(20px, 4.6vh, 46px));
  width: clamp(104px, 14.5vh, 148px);
  height: clamp(104px, 14.5vh, 148px);
  touch-action: none;
}

.joystick {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 44%, rgba(41, 66, 48, 0.42), rgba(9, 17, 12, 0.68) 70%),
    linear-gradient(180deg, rgba(30, 52, 38, 0.48), rgba(7, 14, 10, 0.72));
  border: 1px solid rgba(235, 211, 150, 0.24);
  box-shadow:
    0 16px 38px rgba(3, 9, 6, 0.46),
    inset 0 1px 0 rgba(255, 241, 199, 0.1),
    inset 0 0 28px rgba(2, 8, 5, 0.45);
  backdrop-filter: blur(7px);
  touch-action: none;
}

.joystick-ring {
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  border: 1px dashed rgba(237, 211, 148, 0.2);
  box-shadow: inset 0 0 22px rgba(80, 125, 86, 0.12);
}

.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 43%;
  height: 43%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 28%, rgba(255, 242, 197, 0.3), transparent 32%),
    radial-gradient(circle at 50% 46%, #4e7b58 0%, #2d4e3a 55%, #193326 100%);
  border: 1px solid rgba(248, 224, 155, 0.42);
  box-shadow:
    0 7px 16px rgba(1, 6, 4, 0.48),
    inset 0 0 14px rgba(2, 10, 6, 0.45),
    0 0 18px rgba(137, 185, 114, 0.12);
  transition: box-shadow 0.2s ease;
  will-change: transform;
}

.joystick-knob::after {
  content: "";
  position: absolute;
  inset: 32%;
  border-radius: 50%;
  border: 1px solid rgba(240, 215, 148, 0.3);
  background: radial-gradient(circle at 40% 30%, rgba(255, 232, 159, 0.3), transparent 60%);
}

.joystick.active .joystick-knob {
  box-shadow:
    0 7px 16px rgba(1, 6, 4, 0.48),
    inset 0 0 14px rgba(2, 10, 6, 0.45),
    0 0 26px rgba(236, 198, 105, 0.28);
}

.joystick-knob span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: rgba(255, 232, 165, 0.6);
}

.joystick-runes i {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(238, 209, 141, 0.36);
  box-shadow: 0 0 6px rgba(246, 214, 130, 0.3);
}
.joystick-runes .north { left: 50%; top: 7%; transform: translateX(-50%); }
.joystick-runes .south { left: 50%; bottom: 7%; transform: translateX(-50%); }
.joystick-runes .east { right: 7%; top: 50%; transform: translateY(-50%); }
.joystick-runes .west { left: 7%; top: 50%; transform: translateY(-50%); }

.desktop-hint {
  position: absolute;
  z-index: 8;
  right: calc(var(--safe-right) + 24px);
  bottom: calc(var(--safe-bottom) + 28px);
  display: flex;
  align-items: center;
  gap: 5px;
  color: rgba(227, 213, 177, 0.56);
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: opacity 0.5s ease;
}

.desktop-hint kbd {
  display: grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  padding: 0 4px;
  border-radius: 4px;
  border: 1px solid rgba(235, 211, 150, 0.24);
  background: rgba(13, 23, 17, 0.65);
  color: rgba(244, 231, 196, 0.72);
  font-size: 9px;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.3);
}

.desktop-hint span { margin-left: 5px; }

.compass {
  position: absolute;
  z-index: 8;
  top: calc(var(--safe-top) + 78px);
  right: calc(var(--safe-right) + 23px);
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1px solid rgba(233, 208, 145, 0.18);
  background: rgba(11, 20, 14, 0.5);
  backdrop-filter: blur(5px);
  opacity: 0.75;
}

.compass em {
  position: absolute;
  left: 50%;
  top: 3px;
  transform: translateX(-50%);
  font-style: normal;
  font-size: 7px;
  color: rgba(245, 225, 169, 0.65);
  letter-spacing: 0.1em;
}

.compass-needle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2px;
  height: 10px;
  transform: translate(-50%, -62%);
  background: linear-gradient(to bottom, var(--gold) 0 50%, rgba(226, 211, 167, 0.28) 50%);
  clip-path: polygon(50% 0, 100% 45%, 50% 100%, 0 45%);
}

/* Title screen */
.title-screen {
  position: absolute;
  z-index: 30;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 22px;
  background:
    radial-gradient(ellipse at 50% 44%, rgba(16, 30, 21, 0.18) 0%, rgba(7, 14, 10, 0.55) 55%, rgba(4, 9, 6, 0.86) 100%);
  backdrop-filter: blur(2.5px) saturate(0.9);
  transition: opacity 0.9s ease, backdrop-filter 0.9s ease;
  overflow: hidden;
}

.title-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(50% 40% at 50% 44%, rgba(255, 221, 143, 0.1), transparent 70%);
  pointer-events: none;
}

.title-screen.hidden {
  opacity: 0;
  pointer-events: none;
  backdrop-filter: blur(0) saturate(1);
}

.title-glow {
  position: absolute;
  width: min(90vw, 720px);
  height: min(90vw, 720px);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 220, 140, 0.075) 0%, rgba(120, 179, 112, 0.04) 35%, transparent 68%);
  animation: breathe 7s ease-in-out infinite;
}

@keyframes breathe {
  0%, 100% { transform: scale(0.92); opacity: 0.75; }
  50% { transform: scale(1.08); opacity: 1; }
}

.title-frame {
  position: relative;
  width: min(540px, 92vw);
  padding: clamp(30px, 5vh, 52px) clamp(22px, 5vw, 58px) clamp(26px, 4.4vh, 40px);
  text-align: center;
  background:
    linear-gradient(180deg, rgba(19, 32, 23, 0.88), rgba(9, 18, 13, 0.9)),
    radial-gradient(80% 60% at 50% 0%, rgba(100, 139, 91, 0.18), transparent 70%);
  border: 1px solid rgba(234, 205, 134, 0.34);
  box-shadow:
    0 42px 120px rgba(2, 7, 4, 0.7),
    inset 0 1px 0 rgba(255, 242, 200, 0.1),
    inset 0 0 80px rgba(0, 0, 0, 0.24);
  animation: title-in 1.1s cubic-bezier(.2,.9,.25,1) both;
}

@keyframes title-in {
  from { opacity: 0; transform: translateY(18px) scale(0.985); }
  to { opacity: 1; transform: none; }
}

.title-frame::before,
.title-frame::after {
  content: "";
  position: absolute;
  pointer-events: none;
}
.title-frame::before {
  inset: 7px;
  border: 1px solid rgba(234, 205, 134, 0.12);
}
.title-frame::after {
  left: 50%;
  bottom: -1px;
  width: 46%;
  height: 2px;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, rgba(255, 223, 137, 0.55), transparent);
}

.corner {
  position: absolute;
  width: 20px;
  height: 20px;
  border-color: rgba(245, 218, 146, 0.5);
  border-style: solid;
  pointer-events: none;
}
.corner.tl { top: 13px; left: 13px; border-width: 1px 0 0 1px; }
.corner.tr { top: 13px; right: 13px; border-width: 1px 1px 0 0; }
.corner.bl { bottom: 13px; left: 13px; border-width: 0 0 1px 1px; }
.corner.br { bottom: 13px; right: 13px; border-width: 0 1px 1px 0; }

.eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  margin: 0 0 11px;
  font-size: 9px;
  letter-spacing: 0.48em;
  text-transform: uppercase;
  color: rgba(222, 204, 158, 0.62);
}
.eyebrow span { width: 34px; height: 1px; background: linear-gradient(90deg, transparent, rgba(229, 201, 128, 0.5)); }
.eyebrow span:last-child { transform: scaleX(-1); }

.title-frame h1 {
  margin: 0;
  font-size: clamp(42px, 8vw, 68px);
  font-weight: 400;
  line-height: 0.94;
  letter-spacing: 0.035em;
  color: #f8edce;
  text-shadow:
    0 2px 0 rgba(58, 43, 19, 0.38),
    0 0 32px rgba(255, 206, 104, 0.18),
    0 8px 30px rgba(0, 0, 0, 0.45);
  background: linear-gradient(180deg, #fff5d8 8%, #efd692 52%, #c89e55 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  margin: 10px 0 0;
  font-size: 10px;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: rgba(225, 208, 164, 0.58);
}

.title-rule {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 24px 0 20px;
  color: rgba(240, 207, 118, 0.75);
  font-size: 12px;
}
.title-rule i { width: 58px; height: 1px; background: linear-gradient(90deg, transparent, rgba(226, 197, 121, 0.4)); }
.title-rule i:last-child { transform: scaleX(-1); }
.title-rule b { font-weight: 400; text-shadow: 0 0 12px rgba(255, 214, 107, 0.5); }

.story {
  margin: 0 auto;
  max-width: 380px;
  font-size: 14px;
  line-height: 1.7;
  color: rgba(229, 217, 185, 0.72);
  font-style: italic;
  letter-spacing: 0.01em;
}

.start-button {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 186px;
  margin: 27px auto 0;
  padding: 13px 30px 12px;
  border: 1px solid rgba(255, 228, 151, 0.75);
  border-radius: 3px;
  background:
    linear-gradient(180deg, rgba(222, 185, 96, 0.24), rgba(124, 91, 32, 0.2)),
    rgba(15, 27, 19, 0.6);
  color: #fff3cd;
  font-family: inherit;
  cursor: pointer;
  overflow: hidden;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.4),
    0 8px 30px rgba(4, 10, 6, 0.4),
    inset 0 1px 0 rgba(255, 246, 212, 0.18);
  transition: transform 0.2s ease, box-shadow 0.3s ease, background 0.3s ease;
}

.start-button:hover {
  transform: translateY(-2px);
  background:
    linear-gradient(180deg, rgba(233, 198, 108, 0.34), rgba(141, 104, 39, 0.28)),
    rgba(18, 32, 23, 0.7);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.4),
    0 12px 36px rgba(4, 10, 6, 0.5),
    0 0 26px rgba(231, 188, 82, 0.18),
    inset 0 1px 0 rgba(255, 246, 212, 0.24);
}
.start-button:active { transform: translateY(0) scale(0.985); }

.btn-label {
  font-size: 17px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  padding-left: 0.3em;
}
.btn-sub {
  font-size: 8px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: rgba(235, 211, 153, 0.58);
}
.btn-glint {
  position: absolute;
  top: -40%;
  left: -60%;
  width: 45%;
  height: 180%;
  transform: rotate(20deg);
  background: linear-gradient(90deg, transparent, rgba(255, 245, 209, 0.2), transparent);
  animation: glint 4.8s ease-in-out infinite;
}
@keyframes glint {
  0%, 62% { left: -60%; }
  82%, 100% { left: 130%; }
}

.controls-card {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 17px;
  margin: 27px auto 0;
  padding: 11px 17px;
  width: fit-content;
  border-top: 1px solid rgba(226, 202, 140, 0.12);
  color: rgba(220, 210, 180, 0.58);
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.control { display: flex; align-items: center; gap: 8px; }
.control strong { color: rgba(239, 225, 188, 0.82); font-weight: 500; }
.control-divider { width: 1px; height: 18px; background: rgba(231, 206, 139, 0.14); }

.mini-stick {
  position: relative;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid rgba(236, 212, 150, 0.3);
  background: rgba(17, 30, 21, 0.5);
}
.mini-stick i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 9px;
  height: 9px;
  transform: translate(-50%, -40%);
  border-radius: 50%;
  background: #547e5b;
  border: 1px solid rgba(241, 217, 151, 0.32);
}
.mini-keys { display: flex; gap: 2px; }
.mini-keys b {
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  font-size: 7px;
  font-weight: 400;
  border-radius: 2px;
  border: 1px solid rgba(234, 208, 145, 0.26);
  color: rgba(240, 226, 189, 0.62);
  background: rgba(14, 25, 18, 0.5);
}
.title-foot {
  margin: 16px 0 0;
  font-size: 9px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: rgba(213, 195, 151, 0.42);
}

/* Win banner */
.win-banner {
  position: absolute;
  z-index: 25;
  left: 50%;
  top: calc(var(--safe-top) + 110px);
  transform: translate(-50%, -14px);
  width: min(440px, 90vw);
  padding: 22px 28px 20px;
  text-align: center;
  border-radius: 4px;
  border: 1px solid rgba(255, 223, 135, 0.5);
  background:
    radial-gradient(90% 80% at 50% 0%, rgba(224, 184, 87, 0.18), transparent 70%),
    linear-gradient(180deg, rgba(22, 36, 25, 0.94), rgba(10, 19, 13, 0.94));
  box-shadow:
    0 28px 80px rgba(2, 7, 4, 0.65),
    0 0 40px rgba(241, 196, 81, 0.16),
    inset 0 1px 0 rgba(255, 246, 211, 0.16);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(.2,.9,.3,1);
}
.win-banner.visible { opacity: 1; transform: translate(-50%, 0); pointer-events: auto; }
.win-rays {
  position: absolute;
  inset: -60% -20% auto;
  height: 150%;
  background: conic-gradient(from 0deg at 50% 50%, transparent 0 12deg, rgba(255, 226, 152, 0.06) 12deg 18deg, transparent 18deg 38deg, rgba(255, 226, 152, 0.05) 38deg 45deg, transparent 45deg 70deg, rgba(255, 226, 152, 0.07) 70deg 77deg, transparent 77deg 100%);
  animation: slow-spin 26s linear infinite;
  pointer-events: none;
  z-index: -1;
}
@keyframes slow-spin { to { transform: rotate(360deg); } }
.win-eyebrow { margin: 0 0 4px; font-size: 8px; text-transform: uppercase; letter-spacing: 0.38em; color: rgba(220, 192, 121, 0.72); }
.win-banner h2 {
  margin: 0;
  font-size: clamp(24px, 4.4vw, 32px);
  font-weight: 400;
  letter-spacing: 0.04em;
  color: #ffe9af;
  text-shadow: 0 0 26px rgba(255, 208, 93, 0.25);
}
.win-banner p { margin: 9px 0 0; font-size: 13px; line-height: 1.5; color: rgba(230, 217, 181, 0.72); font-style: italic; }
.win-dismiss {
  margin-top: 16px;
  padding: 7px 18px;
  border-radius: 2px;
  border: 1px solid rgba(236, 208, 133, 0.38);
  background: rgba(16, 29, 20, 0.5);
  color: rgba(250, 235, 192, 0.86);
  font-family: inherit;
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  cursor: pointer;
}
.win-dismiss:hover { border-color: rgba(255, 225, 145, 0.7); color: #fff2c7; }

.fatal {
  position: absolute;
  z-index: 50;
  inset: 0;
  display: grid;
  place-content: center;
  gap: 8px;
  text-align: center;
  background: #101b14;
  color: #e7ddc0;
}
.fatal small { color: #a89678; max-width: 70vw; }

@media (max-width: 620px) {
  .hud-top { top: calc(var(--safe-top) + 10px); left: calc(var(--safe-left) + 10px); right: calc(var(--safe-right) + 10px); }
  .brand { padding: 6px 10px 6px 7px; gap: 7px; }
  .brand-mark { width: 27px; height: 27px; }
  .brand-mark svg { width: 18px; height: 18px; }
  .brand-text strong { font-size: 12px; letter-spacing: 0.13em; }
  .brand-text small { display: none; }
  .quest { padding: 7px 13px 8px; gap: 5px; top: 2px; }
  .quest-label { font-size: 7px; letter-spacing: 0.27em; }
  .bloom-track { gap: 4px; }
  .bloom { width: 13px; height: 13px; font-size: 12px; }
  .compass { display: none; }
  .desktop-hint { display: none; }
  .toast { bottom: calc(var(--safe-bottom) + 126px); font-size: 11px; padding: 8px 15px; }
  .title-screen { padding: 14px; }
  .title-frame { padding: 30px 20px 24px; }
  .story { font-size: 12.5px; line-height: 1.6; }
  .wide-only { display: none; }
  .controls-card { gap: 12px; margin-top: 22px; }
  .start-button { margin-top: 23px; }
}

