  px(ctx, cx + 2, 15, 4, 37, "#60665b");
  px(ctx, cx - 5, 0, 11, 11, OUTLINE);
  px(ctx, cx - 3, 2, 7, 8, "#7a8071");
  px(ctx, cx - 2, 3, 2, 5, "#a1a38e");
  // rune
  px(ctx, cx - 1, 24, 3, 9, "#5d8f82");
  px(ctx, cx - 4, 27, 9, 2, "#5d8f82");
