import { PLAYER } from "./config.js";
import { makePlayerSprites, drawShadow } from "./art.js";

export class Player {
  constructor(x = PLAYER.startX, y = PLAYER.startY) {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.radius = PLAYER.radius;
    this.facing = "down";
    this.art = makePlayerSprites();
    this.frame = 0;
    this.walkDistance = 0;
    this.walking = false;
    this.justStepped = false;
    this.speed = 0;
    this.lanternSwing = 0;
    this.spawn = { x, y };
  }

  update(dt, input, world) {
    const magnitude = Math.min(1, Math.hypot(input.x, input.y));
    const moving = magnitude > 0.06;
    const targetVx = moving ? (input.x / (magnitude || 1)) * PLAYER.speed * magnitude : 0;
    const targetVy = moving ? (input.y / (magnitude || 1)) * PLAYER.speed * magnitude : 0;
    const response = moving ? 13.5 : 10.5;
    const blend = 1 - Math.exp(-response * dt);
    this.vx += (targetVx - this.vx) * blend;
    this.vy += (targetVy - this.vy) * blend;

    if (!moving && Math.hypot(this.vx, this.vy) < 0.35) {
      this.vx = 0;
      this.vy = 0;
    }

    const nextX = this.x + this.vx * dt;
    if (!world.isBlocked(nextX, this.y, this.radius)) this.x = nextX;
    else this.vx *= -0.06;

    const nextY = this.y + this.vy * dt;
    if (!world.isBlocked(this.x, nextY, this.radius)) this.y = nextY;
    else this.vy *= -0.06;

    this.speed = Math.hypot(this.vx, this.vy);
    this.walking = this.speed > 6;
    this.justStepped = false;
    if (this.walking) {
      const previous = this.frame;
      this.walkDistance += this.speed * dt;
      this.frame = Math.floor(this.walkDistance / 8.5) % 4;
      if (this.frame !== previous && (this.frame === 0 || this.frame === 2)) this.justStepped = true;
      this.lanternSwing = Math.sin(this.walkDistance * 0.08) * 1.5;
    } else {
      this.frame = 1;
      this.walkDistance = 0;
      this.lanternSwing *= 0.9;
    }

    const ax = Math.abs(this.vx);
    const ay = Math.abs(this.vy);
    if (ax > 7 || ay > 7) {
      if (ax >= ay) this.facing = this.vx > 0 ? "right" : "left";
      else this.facing = this.vy > 0 ? "down" : "up";
    }
  }

  get sortY() {
    return this.y + 1;
  }

  getLanternPosition() {
    if (this.facing === "left") return { x: this.x - 10, y: this.y - 10 + this.lanternSwing * 0.25 };
    if (this.facing === "right") return { x: this.x + 10, y: this.y - 10 + this.lanternSwing * 0.25 };
    return { x: this.x + 8, y: this.y - 10 + this.lanternSwing * 0.25 };
  }

  draw(ctx, cam) {
    const x = Math.round(this.x - cam.x + cam.viewW / 2);
    const y = Math.round(this.y - cam.y + cam.viewH / 2);
    drawShadow(ctx, x, y - 1, 7, 3, 0.26);
    const sprite = this.art.sprites[this.facing][this.frame];
    ctx.drawImage(sprite, x - Math.floor(this.art.width / 2), y - this.art.base);
  }
}

// Unified keyboard + touch input. The joystick is analog, but has a tiny
// dead-zone and a soft spring-back so small thumbs still feel deliberate.
export class Input {
  constructor({ joystick, knob }) {
    this.joystick = joystick;
    this.knob = knob;
    this.keys = new Set();
    this.stick = { x: 0, y: 0, active: false };
    this.pointerId = null;
    this.center = { x: 0, y: 0 };
    this.maxRadius = 40;
    this.keyboardUsed = false;
    this.touchUsed = false;
    this.onActivity = null;

    window.addEventListener("keydown", (event) => {
      if (event.repeat) return;
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "KeyW", "KeyA", "KeyS", "KeyD", "Space"].includes(event.code)) {
        if (event.code !== "Space") event.preventDefault();
        this.keys.add(event.code);
        this.keyboardUsed = true;
        this.onActivity?.("key");
      }
    });
    window.addEventListener("keyup", (event) => {
      this.keys.delete(event.code);
    });
    window.addEventListener("blur", () => {
      this.keys.clear();
      this.resetStick();
    });

    const down = (event) => {
      if (this.pointerId !== null) return;
      this.pointerId = event.pointerId;
      this.touchUsed = true;
      this.joystick.classList.add("active");
      const rect = this.joystick.getBoundingClientRect();
      this.center = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
      this.maxRadius = rect.width * 0.31;
      this.joystick.setPointerCapture?.(event.pointerId);
      this.updateStick(event.clientX, event.clientY);
      this.onActivity?.("pointer");
      event.preventDefault();
    };
    const move = (event) => {
      if (event.pointerId !== this.pointerId) return;
      this.updateStick(event.clientX, event.clientY);
      event.preventDefault();
    };
    const up = (event) => {
      if (event.pointerId !== this.pointerId) return;
      this.resetStick();
      event.preventDefault();
    };

    this.joystick.addEventListener("pointerdown", down);
    this.joystick.addEventListener("pointermove", move);
    this.joystick.addEventListener("pointerup", up);
    this.joystick.addEventListener("pointercancel", up);
    this.joystick.addEventListener("lostpointercapture", up);
  }

  updateStick(clientX, clientY) {
    let dx = clientX - this.center.x;
    let dy = clientY - this.center.y;
    const distance = Math.hypot(dx, dy);
    if (distance > this.maxRadius) {
      dx = (dx / distance) * this.maxRadius;
      dy = (dy / distance) * this.maxRadius;
    }
    const nx = dx / this.maxRadius;
    const ny = dy / this.maxRadius;
    const magnitude = Math.hypot(nx, ny);
    const dead = 0.12;
    if (magnitude < dead) {
      this.stick.x = 0;
      this.stick.y = 0;
    } else {
      const scaled = Math.min(1, (magnitude - dead) / (1 - dead));
      this.stick.x = (nx / magnitude) * scaled;
      this.stick.y = (ny / magnitude) * scaled;
    }
    this.stick.active = true;
    this.knob.style.transform = `translate(-50%, -50%) translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px)`;
  }

  resetStick() {
    this.pointerId = null;
    this.stick.x = 0;
    this.stick.y = 0;
    this.stick.active = false;
    this.joystick.classList.remove("active");
    this.knob.style.transform = "translate(-50%, -50%)";
  }

  getVector() {
    let x = 0;
    let y = 0;
    if (this.keys.has("KeyW") || this.keys.has("ArrowUp")) y -= 1;
    if (this.keys.has("KeyS") || this.keys.has("ArrowDown")) y += 1;
    if (this.keys.has("KeyA") || this.keys.has("ArrowLeft")) x -= 1;
    if (this.keys.has("KeyD") || this.keys.has("ArrowRight")) x += 1;
    if (x !== 0 || y !== 0) {
      const length = Math.hypot(x, y);
      x /= length;
      y /= length;
    }
    if (this.stick.active && (this.stick.x !== 0 || this.stick.y !== 0)) {
      if (x === 0 && y === 0) return { x: this.stick.x, y: this.stick.y };
      x += this.stick.x;
      y += this.stick.y;
      const length = Math.hypot(x, y);
      if (length > 1) {
        x /= length;
        y /= length;
      }
    }
    return { x, y };
  }
}

import { CAMERA } from "./config.js";
import { clamp } from "./rng.js";

export class Camera {
  constructor(world) {
    this.world = world;
    this.x = 0;
    this.y = 0;
    this.viewW = 480;
    this.viewH = 300;
    this.targetX = 0;
    this.targetY = 0;
  }

  resize(viewW, viewH) {
    this.viewW = viewW;
    this.viewH = viewH;
  }

  clampToWorld() {
    const halfW = this.viewW / 2;
    const halfH = this.viewH / 2;
    this.x = this.world.width > this.viewW
      ? clamp(this.x, halfW, this.world.width - halfW)
      : this.world.width / 2;
    this.y = this.world.height > this.viewH
      ? clamp(this.y, halfH, this.world.height - halfH)
      : this.world.height / 2;
  }

  snapTo(x, y) {
    this.x = x;
    this.y = y + CAMERA.offsetY;
    this.clampToWorld();
  }

  update(dt, player, speedRatio = 0, intensity = 1) {
    const lookX = player.vx * (CAMERA.lookAhead / 62) * intensity;
    const lookY = player.vy * (CAMERA.lookAhead * 0.6 / 62) * intensity;
    this.targetX = player.x + lookX;
    this.targetY = player.y + CAMERA.offsetY + lookY;
    const blend = 1 - Math.exp(-CAMERA.damping * dt);
    this.x += (this.targetX - this.x) * blend;
    this.y += (this.targetY - this.y) * blend;
    this.clampToWorld();
  }

  drift(dt, time) {
    // Gentle establishing drift while the title card is open.
    const targetX = this.world.width / 2 + Math.sin(time * 0.055) * 120;
    const targetY = 930 + Math.cos(time * 0.045) * 70;
    const blend = 1 - Math.exp(-0.55 * dt);
    this.x += (targetX - this.x) * blend;
    this.y += (targetY - this.y) * blend;
    this.clampToWorld();
  }
}

// A tiny procedural soundscape: soft wind, bird calls and a chime for each
// starbloom. No audio files, no autoplay before the start gesture.
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ready = false;
    this.nextBird = 5;
    try {
      this.muted = localStorage.getItem("hollowbrook-muted") === "1";
    } catch {
      this.muted = false;
    }
  }

  start() {
    if (this.ready) {
      if (this.ctx?.state === "suspended") this.ctx.resume();
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    try {
      this.ctx = new AudioContext();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.7;
      this.master.connect(this.ctx.destination);
      this.ready = true;
      this.startWind();
    } catch {
      this.ready = false;
    }
  }

  startWind() {
    const ctx = this.ctx;
    const length = Math.floor(ctx.sampleRate * 3.5);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      last = last * 0.985 + (Math.random() * 2 - 1) * 0.015;
      data[i] = last * 2.4;
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 460;
    const gain = ctx.createGain();
    gain.gain.value = 0.16;
    source.connect(filter).connect(gain).connect(this.master);
    source.start();
  }

  setMuted(muted) {
    this.muted = muted;
    try {
      localStorage.setItem("hollowbrook-muted", muted ? "1" : "0");
    } catch {}
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.7, this.ctx.currentTime + 0.2);
    }
  }

  tone(freq, duration = 0.25, type = "sine", volume = 0.05, delay = 0) {
    if (!this.ready || !this.ctx) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0, ctx.currentTime + delay);
    gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + delay + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + delay + duration);
    osc.connect(gain).connect(this.master);
    osc.start(ctx.currentTime + delay);
    osc.stop(ctx.currentTime + delay + duration + 0.05);
  }

  chime(index = 0) {
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5, 1568];
    const base = notes[index % notes.length];
    this.tone(base, 0.7, "sine", 0.08);
    this.tone(base * 1.5, 0.55, "sine", 0.035, 0.06);
    this.tone(base * 2, 0.4, "triangle", 0.018, 0.12);
  }

  step() {
    if (!this.ready || !this.ctx) return;
    const ctx = this.ctx;
    const length = Math.floor(ctx.sampleRate * 0.055);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 3) * 0.3;
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 340;
    const gain = ctx.createGain();
    gain.gain.value = 0.14;
    source.connect(filter).connect(gain).connect(this.master);
    source.start();
  }

  startJingle() {
    this.tone(392, 0.5, "sine", 0.045);
    this.tone(523.25, 0.6, "sine", 0.04, 0.15);
    this.tone(659.25, 0.8, "sine", 0.035, 0.3);
  }

  complete() {
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => this.tone(f, 1.4, "sine", 0.06, i * 0.16));
    this.tone(1568, 1.8, "triangle", 0.02, 0.65);
  }

  update(dt) {
    if (!this.ready || this.muted) return;
    this.nextBird -= dt;
    if (this.nextBird <= 0) {
      this.nextBird = 7 + Math.random() * 9;
      const base = 1100 + Math.random() * 900;
      this.tone(base, 0.09, "sine", 0.022);
      this.tone(base * 1.18, 0.07, "sine", 0.016, 0.1);
      if (Math.random() > 0.55) this.tone(base * 0.9, 0.08, "sine", 0.014, 0.23);
    }
  }
}

import { rand, mulberry32 } from "./rng.js";

const rng = mulberry32(9090);

export class Particles {
  constructor() {
    this.items = [];
    this.ambient = [];
    this.screenMotes = [];
    for (let i = 0; i < 46; i += 1) {
      this.screenMotes.push({
        x: rng(), y: rng(), z: 0.35 + rng() * 0.8, phase: rng() * 10, drift: 0.1 + rng() * 0.3,
      });
    }
  }

  spawn(x, y, options = {}) {
    const {
      count = 10,
      colors = ["#f6d66d", "#fff1b7", "#e9b84f"],
      speed = 24,
      spread = Math.PI * 2,
      direction = 0,
      gravity = 0,
      life = 0.8,
      size = 1,
      kind = "spark",
      rise = 0,
    } = options;
    for (let i = 0; i < count; i += 1) {
      const angle = direction + (rng() - 0.5) * spread;
      const velocity = speed * (0.35 + rng() * 0.8);
      this.items.push({
        x, y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity + rise,
        gravity,
        life: life * (0.65 + rng() * 0.7),
        maxLife: life,
        color: colors[Math.floor(rng() * colors.length)],
        size: size + (rng() > 0.8 ? 1 : 0),
        kind,
        phase: rng() * 6,
      });
    }
  }

  burstBloom(x, y) {
    this.spawn(x, y - 12, { count: 24, speed: 48, life: 1.2, gravity: 12, size: 1 });
    this.spawn(x, y - 10, { count: 10, speed: 24, life: 1.8, colors: ["#f8c8d4", "#f6e2a4", "#ffffff"], gravity: 5, size: 1, kind: "petal" });
  }

  stepDust(x, y) {
    this.spawn(x, y, {
      count: 3,
      speed: 8,
      spread: 2.2,
      life: 0.5,
      colors: ["#b9a779", "#9c8e65", "#d0bd8c"],
      gravity: -4,
      size: 1,
      kind: "dust",
    });
  }

  smoke(x, y, scale = 1) {
    this.items.push({
      x: x + rand(rng, -2, 2),
      y,
      vx: rand(rng, -3, 3) + 1.4,
      vy: rand(rng, -10, -6) * scale,
      gravity: -1.2,
      life: rand(rng, 2.4, 4.3),
      maxLife: 4.3,
      color: "#cfd3c4",
      size: rand(rng, 2, 3.4) * scale,
      kind: "smoke",
      phase: rng() * 6,
    });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i -= 1) {
      const p = this.items[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.items.splice(i, 1);
        continue;
      }
      p.vy += p.gravity * dt;
      if (p.kind === "smoke") {
        p.vx += Math.sin(p.phase + p.life) * 1.1 * dt;
        p.size += dt * 1.6;
      }
      if (p.kind === "petal") {
        p.vx += Math.sin(p.life * 5 + p.phase) * 9 * dt;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  }

  draw(ctx, cam) {
    const left = cam.x - cam.viewW / 2;
    const top = cam.y - cam.viewH / 2;
    ctx.save();
    for (const p of this.items) {
      const x = p.x - left;
      const y = p.y - top;
      if (x < -20 || y < -20 || x > cam.viewW + 20 || y > cam.viewH + 20) continue;
      const t = Math.max(0, p.life / p.maxLife);
      if (p.kind === "smoke") {
        ctx.globalCompositeOperation = "source-over";
        ctx.fillStyle = `rgba(198, 203, 191, ${t * 0.1})`;
        ctx.fillRect(Math.round(x), Math.round(y), Math.ceil(p.size), Math.ceil(p.size));
        ctx.fillStyle = `rgba(222, 224, 210, ${t * 0.07})`;
        ctx.fillRect(Math.round(x) + 1, Math.round(y) - 1, Math.ceil(p.size * 0.7), Math.ceil(p.size * 0.7));
      } else if (p.kind === "dust") {
        ctx.globalCompositeOperation = "source-over";
        ctx.fillStyle = p.color;
        ctx.globalAlpha = t * 0.45;
        ctx.fillRect(Math.round(x), Math.round(y), p.size, p.size);
        ctx.globalAlpha = 1;
      } else {
        ctx.globalCompositeOperation = "lighter";
        ctx.fillStyle = p.color;
        const flicker = p.kind === "petal" ? 0.8 : 0.55 + Math.sin(p.phase + p.life * 11) * 0.35;
        ctx.globalAlpha = Math.min(1, t * 1.4) * flicker;
        ctx.fillRect(Math.round(x), Math.round(y), p.size, p.size);
        if (p.kind === "petal") {
          ctx.globalAlpha = Math.min(1, t) * 0.6;
          ctx.fillRect(Math.round(x) + 1, Math.round(y), 1, 1);
        }
        ctx.globalAlpha = 1;
      }
    }
    ctx.restore();
  }

  drawMotes(ctx, time, cam, reduced = false) {
    if (reduced) return;
    const w = cam.viewW;
    const h = cam.viewH;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const m of this.screenMotes) {
      const x = ((m.x + Math.sin(time * m.drift + m.phase) * 0.03 + 1) % 1) * w;
      const y = ((m.y + Math.cos(time * m.drift * 0.7 + m.phase) * 0.02 + 1) % 1) * h;
      const alpha = 0.1 + Math.sin(time * 1.7 + m.phase) * 0.06;
      ctx.fillStyle = `rgba(255, 237, 168, ${alpha * m.z})`;
      ctx.fillRect(Math.round(x), Math.round(y), 1, 1);
      if (m.z > 1) ctx.fillRect(Math.round(x) + 1, Math.round(y), 1, 1);
    }
    ctx.restore();
  }
}

import { WORLD, PLAYER, BLOOM_POSITIONS } from "./config.js";
import { World } from "./world.js";
import { Player } from "./player.js";
import { Camera } from "./camera.js";
import { Input } from "./input.js";
import { Particles } from "./particles.js";
import { Sound } from "./audio.js";
import { clamp } from "./rng.js";

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d", { alpha: false });
const titleScreen = document.getElementById("title-screen");
const startButton = document.getElementById("start-button");
const soundToggle = document.getElementById("sound-toggle");
const toast = document.getElementById("toast");
const track = document.getElementById("bloom-track");
const winBanner = document.getElementById("win-banner");
const winDismiss = document.getElementById("win-dismiss");
const quest = document.getElementById("quest");
const fatal = document.getElementById("fatal");
const fatalMessage = document.getElementById("fatal-message");
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const state = {
  mode: "title",
  time: 0,
  gathered: 0,
  won: false,
  winDelay: 0,
  shrine: 0,
  toastTimer: 0,
  toastDuration: 0,
  lavaLamp: 0,
};

let world;
let player;
let camera;
let input;
let particles;
let sound;
let smokeTimers = [];
let lanternSparkle = 0;

const bloomIcons = [];

function buildHud() {
  BLOOM_POSITIONS.forEach((spot, index) => {
    const icon = document.createElement("span");
    icon.className = "bloom";
    icon.dataset.index = String(index);
    icon.setAttribute("title", spot.name);
    track.appendChild(icon);
    bloomIcons.push(icon);
  });
  updateHud();
}

function updateHud() {
  track.setAttribute("aria-label", `${state.gathered} of ${BLOOM_POSITIONS.length} starblooms gathered`);
  bloomIcons.forEach((icon, index) => {
    icon.classList.toggle("filled", index < state.gathered);
  });
  quest.classList.toggle("complete", state.gathered === BLOOM_POSITIONS.length);
}

function popBloom(index) {
  const icon = bloomIcons[index];
  if (!icon) return;
  icon.classList.remove("pop");
  // Restart the CSS animation without forcing a full layout read.
  requestAnimationFrame(() => icon.classList.add("pop"));
}

function showToast(message, duration = 3600, gold = false) {
  toast.textContent = message;
  toast.classList.toggle("gold", gold);
  toast.classList.add("visible");
  state.toastTimer = duration / 1000;
  state.toastDuration = duration / 1000;
}

function startGame() {
  if (state.mode !== "title") return;
  state.mode = "playing";
  document.body.classList.remove("is-title");
  document.body.classList.add("is-playing");
  titleScreen.classList.add("hidden");
  sound.start();
  sound.startJingle();
  window.setTimeout(() => showToast("Six starblooms are hiding in the valley. Follow the old paths.", 4600), 550);
  camera.snapTo(player.x, player.y);
  camera.x = player.x;
  camera.y = player.y - 22;
  camera.clampToWorld();
}

function collectBloom(bloom) {
  if (bloom.collected) return;
  bloom.collected = true;
  state.gathered += 1;
  popBloom(bloom.index);
  updateHud();
  particles.burstBloom(bloom.x, bloom.y);
  sound.chime(state.gathered - 1);
  const left = BLOOM_POSITIONS.length - state.gathered;
  if (left > 0) {
    showToast(`✦ Starbloom gathered at ${bloom.name}  ·  ${state.gathered} / ${BLOOM_POSITIONS.length}`, 3300, true);
  } else {
    showToast("✦ The last starbloom wakes. The shrine is singing!", 4400, true);
    state.won = true;
    state.winDelay = 1.15;
    sound.complete();
    particles.spawn(player.x, player.y - 22, {
      count: 48, speed: 70, life: 2.1, gravity: 9, colors: ["#ffe7a1", "#fff6cf", "#f4c65d", "#f8b7c8"], size: 1,
    });
  }
}

function checkPickups() {
  if (state.mode !== "playing") return;
  for (const bloom of world.blooms) {
    if (bloom.collected) continue;
    const dx = player.x - bloom.x;
    const dy = player.y - (bloom.y - 7);
    if (dx * dx + dy * dy < 19 * 19) collectBloom(bloom);
  }
}

function resize() {
  const cssWidth = Math.max(1, window.innerWidth);
  const cssHeight = Math.max(1, window.innerHeight);
  const minDim = Math.min(cssWidth, cssHeight);
  let zoom = clamp(Math.round(minDim / 300), 2, 4);
  if (minDim < 340) zoom = 2;
  if (cssHeight < 380) zoom = 2;
  const width = Math.max(160, Math.ceil(cssWidth / zoom));
  const height = Math.max(140, Math.ceil(cssHeight / zoom));
  canvas.width = width;
  canvas.height = height;
  canvas.style.width = `${cssWidth}px`;
  canvas.style.height = `${cssHeight}px`;
  ctx.imageSmoothingEnabled = false;
  if (camera) {
    camera.resize(width, height);
    camera.clampToWorld();
  }
  document.documentElement.style.setProperty("--art-zoom", String(zoom));
}

function drawLanternLight(cam, time) {
  const p = player.getLanternPosition();
  const x = p.x - cam.x + cam.viewW / 2;
  const y = p.y - cam.y + cam.viewH / 2;
  const flicker = 0.9 + Math.sin(time * 7.3) * 0.07 + Math.sin(time * 13.7) * 0.03;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  // soft light pooled on the ground
  const pool = ctx.createRadialGradient(x, y + 12, 1, x, y + 12, 38);
  pool.addColorStop(0, `rgba(255, 206, 100, ${0.11 * flicker})`);
  pool.addColorStop(0.55, `rgba(255, 188, 78, ${0.04 * flicker})`);
  pool.addColorStop(1, "rgba(255, 180, 70, 0)");
  ctx.fillStyle = pool;
  ctx.fillRect(x - 40, y - 28, 80, 80);
  // warm halo around the little lantern
  const halo = ctx.createRadialGradient(x, y, 1, x, y, 28);
  halo.addColorStop(0, `rgba(255, 231, 156, ${0.26 * flicker})`);
  halo.addColorStop(0.35, `rgba(255, 204, 94, ${0.08 * flicker})`);
  halo.addColorStop(1, "rgba(255, 198, 84, 0)");
  ctx.fillStyle = halo;
  ctx.fillRect(x - 30, y - 30, 60, 60);
  ctx.restore();
}

function updateSmoke(dt) {
  for (let i = 0; i < world.smokeSources.length; i += 1) {
    const source = world.smokeSources[i];
    const dx = source.x - camera.x;
    const dy = source.y - camera.y;
    if (Math.abs(dx) > camera.viewW * 0.8 || Math.abs(dy) > camera.viewH * 0.9) continue;
    smokeTimers[i] = (smokeTimers[i] || 0) - dt;
    if (smokeTimers[i] <= 0) {
      smokeTimers[i] = source.rate * (0.8 + Math.random() * 0.45);
      particles.smoke(source.x, source.y, i === 0 ? 0.9 : 1.15);
    }
  }
}

function render() {
  const cam = camera;
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#27452f";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  world.drawGround(ctx, cam);
  world.drawWater(ctx, cam, state.time);

  // Ground-level lantern warmth is laid down before props.
  drawLanternLight(cam, state.time);

  const entries = [];
  for (const prop of world.getVisibleProps(cam)) {
    entries.push({ sortY: prop.sortY, kind: "prop", value: prop });
  }
  for (const bloom of world.blooms) {
    if (bloom.collected) continue;
    if (bloom.x < cam.x - cam.viewW / 2 - 30 || bloom.x > cam.x + cam.viewW / 2 + 30) continue;
    if (bloom.y < cam.y - cam.viewH / 2 - 40 || bloom.y > cam.y + cam.viewH / 2 + 40) continue;
    entries.push({ sortY: bloom.y, kind: "bloom", value: bloom });
  }
  entries.push({ sortY: player.sortY, kind: "player", value: player });
  entries.sort((a, b) => a.sortY - b.sortY);

  for (const entry of entries) {
    if (entry.kind === "prop") world.drawProp(ctx, entry.value, cam);
    else if (entry.kind === "bloom") world.drawBloom(ctx, entry.value, cam, state.time);
    else entry.value.draw(ctx, cam);
  }

  world.drawAmbient(ctx, cam, state.time);
  particles.draw(ctx, cam);
  particles.drawMotes(ctx, state.time, cam, reducedMotion);

  if (state.shrine > 0.005) {
    world.drawShrineBeam(ctx, cam, state.time, state.shrine);
    if (state.shrine > 0.3) {
      world.drawAmbient(ctx, cam, state.time);
    }
  }

  // A pale edge fog frames the valley without hiding the art.
  const fog = ctx.createLinearGradient(0, 0, 0, canvas.height);
  fog.addColorStop(0, "rgba(210, 226, 196, 0.045)");
  fog.addColorStop(0.2, "rgba(210, 226, 196, 0)");
  fog.addColorStop(0.82, "rgba(20, 36, 25, 0)");
  fog.addColorStop(1, "rgba(20, 36, 25, 0.08)");
  ctx.fillStyle = fog;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

let last = performance.now();

function frame(now) {
  const raw = (now - last) / 1000;
  last = now;
  const dt = Math.min(0.05, Math.max(0.0001, raw));
  state.time += dt;

  if (state.mode === "title") {
    camera.drift(dt, state.time);
    player.update(dt, { x: 0, y: 0 }, world);
  } else {
    const vector = input.getVector();
    player.update(dt, vector, world);
    camera.update(dt, player);
    checkPickups();

    if (player.justStepped) {
      particles.stepDust(player.x, player.y + 1);
      sound.step();
    }

    if (!reducedMotion) {
      lanternSparkle -= dt;
      if (lanternSparkle <= 0) {
        lanternSparkle = 0.7 + Math.random() * 0.6;
        const p = player.getLanternPosition();
        particles.spawn(p.x, p.y, { count: 1, speed: 5, life: 0.7, gravity: -10, colors: ["#ffdf8a", "#fff1b3"], size: 1 });
      }
    }

    if (state.winDelay > 0) {
      state.winDelay -= dt;
      if (state.winDelay <= 0 && !winBanner.classList.contains("visible")) {
        winBanner.classList.add("visible");
      }
    }
  }

  state.shrine += ((state.won ? 1 : 0) - state.shrine) * (1 - Math.exp(-1.6 * dt));

  if (state.toastTimer > 0) {
    state.toastTimer -= dt;
    if (state.toastTimer <= 0) toast.classList.remove("visible");
  }

  particles.update(dt);
  updateSmoke(dt);
  sound.update(dt);
  render();
  requestAnimationFrame(frame);
}

function setupEvents() {
  startButton.addEventListener("click", startGame);

  window.addEventListener("keydown", (event) => {
    if (state.mode === "title" && (event.code === "Enter" || event.code === "Space" || event.code.startsWith("Arrow") || ["KeyW", "KeyA", "KeyS", "KeyD"].includes(event.code))) {
      startGame();
    }
  });

  soundToggle.addEventListener("click", () => {
    if (!sound.ready) sound.start();
    const next = !sound.muted;
    sound.setMuted(next);
    soundToggle.classList.toggle("muted", next);
    soundToggle.setAttribute("aria-pressed", next ? "true" : "false");
    soundToggle.setAttribute("aria-label", next ? "Unmute sound" : "Mute sound");
    if (!next) sound.tone(660, 0.18, "sine", 0.03);
  });

  winDismiss.addEventListener("click", () => winBanner.classList.remove("visible"));

  window.addEventListener("resize", resize);
  window.addEventListener("orientationchange", () => window.setTimeout(resize, 80));
  window.visualViewport?.addEventListener("resize", resize);

  document.addEventListener("visibilitychange", () => {
    last = performance.now();
  });
}

function boot() {
  try {
    if (soundToggle) {
      soundToggle.classList.toggle("muted", false);
    }
    world = new World();
    player = new Player(PLAYER.startX, PLAYER.startY);
    camera = new Camera(world);
    particles = new Particles();
    sound = new Sound();
    input = new Input({
      joystick: document.getElementById("joystick"),
      knob: document.getElementById("joystick-knob"),
    });

    resize();
    camera.snapTo(WORLD.width / 2, 930);
    camera.x = WORLD.width / 2;
    camera.y = 930;
    camera.clampToWorld();
    buildHud();
    setupEvents();

    document.body.classList.add("is-title");
    smokeTimers = world.smokeSources.map(() => Math.random() * 0.4);

    // A tiny debug handle helps future expansion and automated visual checks.
    window.__hollowbrook = {
      world, player, camera, state,
      start: startGame,
      setPosition(x, y) {
        player.x = x;
        player.y = y;
        camera.snapTo(x, y);
      },
      gatherAll() {
        for (const bloom of world.blooms) {
          if (!bloom.collected) {
            player.x = bloom.x;
            player.y = bloom.y;
            checkPickups();
          }
        }
      },
    };

    requestAnimationFrame((time) => {
      last = time;
      requestAnimationFrame(frame);
    });
  } catch (error) {
    console.error(error);
    fatal.hidden = false;
    fatalMessage.textContent = error?.message || String(error);
  }
}

boot();

